const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const W=104,H=72,T=12,biome={water:0,grass:1,forest:2,desert:3,mountain:4,snow:5};
const colors=['#234a55','#879c57','#527746','#b99156','#747b73','#d5d9d0'];
let world=[],people=[],animals=[],towns=[],effects=[],seed=0,year=1,tick=0,paused=false,speed=1,tool='inspect',cam={x:0,y:0,z:1},selected=null,drag=null,acc=0,last=performance.now(),rain=0;
const civDefs={human:{name:'The Hearthwardens',race:'Humans',icon:'♟',color:'#d7a85d',desc:'Adaptable · balanced growth',food:0,wood:0,stone:0,ore:0,tools:0,coin:0},aurelin:{name:'Elderbloom Court',race:'Aurelin',icon:'❋',color:'#86c77f',desc:'Nature specialists · forest-born',food:0,wood:0,stone:0,ore:0,tools:0,coin:0},dwarf:{name:'Ironvein Holds',race:'Dwarves',icon:'⚒',color:'#b887b9',desc:'Mining & craft · stone-born',food:0,wood:0,stone:0,ore:0,tools:0,coin:0}};
let diplomacy={}; const rand=()=>Math.random();const ir=(n)=>Math.floor(rand()*n);const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function noise(x,y,s){let a=Math.sin((x+s*1.71)*.13)*Math.cos((y-s*2.3)*.17),b=Math.sin((x*.071+s)*.31+y*.12),c=Math.cos((y*.052-s)*.4+x*.09);return (a*.5+b*.3+c*.2)}
function generate(){seed=ir(99999);year=1;tick=0;world=Array.from({length:H},(_,y)=>Array.from({length:W},(_,x)=>{let nx=(x-W/2)/(W*.48),ny=(y-H/2)/(H*.49),d=Math.sqrt(nx*nx+ny*ny),island=noise(x,y,seed)+.26*Math.sin(x*.09+seed)+.2*Math.cos(y*.11);let land=island-d*.86+.17;if(land<-.12)return{b:0,food:0,wood:0,stone:0,ore:0,wet:0};let n=noise(x+500,y+400,seed+7),b=land>.59||n>.57?4:land>.43&&y<H*.22?5:n<-.38?3:n>.18?2:1;return{b,food:b===1?2:b===2?2:b===3?0:1,wood:b===2?3:b===1?1:0,stone:b===4?3:1,ore:b===4&&rand()<.4?2:0,wet:0}}));
people=[];animals=[];towns=[];effects=[];selected=null;Object.values(civDefs).forEach(c=>Object.assign(c,{food:40,wood:22,stone:10,ore:4,tools:3,coin:0}));diplomacy={};Object.keys(civDefs).forEach((a,i)=>Object.keys(civDefs).slice(i+1).forEach(b=>diplomacy[a+b]=0));
// Place three starting villages on suitable, separated land.
const centers=[['human',.25,.48],['aurelin',.54,.35],['dwarf',.73,.63]];for(let [id,fx,fy] of centers){let p=findLand(Math.round(W*fx),Math.round(H*fy),id);if(p)foundTown(id,p.x,p.y,true)}
for(let i=0;i<42;i++){let p=randomLand();if(p)animals.push({x:p.x,y:p.y,type:rand()<.65?'deer':'boar',age:ir(8),energy:60+ir(40),dir:rand()*6.28})}
for(let a of Object.keys(diplomacy))diplomacy[a]=rand()<.7?1:0;
document.getElementById('seedLabel').textContent='WORLD '+String(seed).padStart(5,'0'); document.getElementById('worldName').textContent=['The Verdant Reach','Mytherian Isles','The Elderwild','Crown of the First Sea','Westreach'][ir(5)];log(`A new realm awakens. Three peoples settle the shores.`);fit();refresh();}
function findLand(x,y,id){for(let r=0;r<20;r++)for(let yy=Math.max(1,y-r);yy<=Math.min(H-2,y+r);yy++)for(let xx=Math.max(1,x-r);xx<=Math.min(W-2,x+r);xx++)if(Math.abs(xx-x)+Math.abs(yy-y)<=r+2&&world[yy][xx].b>0&&world[yy][xx].b!==5&&(id!=='dwarf'||world[yy][xx].b===4||world[yy][xx].b===1))return{x:xx,y:yy};return null}
function randomLand(){for(let i=0;i<500;i++){let x=ir(W),y=ir(H);if(world[y][x].b>0)return{x,y}}return null}
function foundTown(civ,x,y,initial=false){let t={id:towns.length,civ,x,y,name:(civ==='human'?['Oakwatch','Westmere','Brightford']:civ==='aurelin'?['Mossvale','Fernhollow','Greenglade']:['Deepdelve','Ironroot','Stonehall'])[ir(3)],level:1,age:0,farms:0,homes:1,market:0,wall:0,ship:false};towns.push(t);let amount=initial?7:4;for(let i=0;i<amount;i++)spawnPerson(civ,x+rand()*2-1,y+rand()*2-1,t.id,ir(35)+15);if(!initial)log(`${civDefs[civ].name} founded ${t.name}.`);}
function spawnPerson(civ,x,y,town,age){people.push({id:Math.random(),civ,x,y,home:town,age:age||ir(38),energy:65+ir(30),hunger:rand()*22,health:100,job:'gather',target:null,work:0,gender:rand()<.5?'♀':'♂',preg:0,gear:0,level:1,dead:false,ship:false})}
function log(text){let el=document.getElementById('log'),d=document.createElement('div');d.innerHTML=`<b>Y${year}</b> · ${text}`;el.prepend(d);while(el.children.length>8)el.lastChild.remove()}

function nearbyTile(x,y,fn,r=4){for(let j=Math.max(0,Math.floor(y-r));j<Math.min(H,Math.ceil(y+r));j++)for(let i=Math.max(0,Math.floor(x-r));i<Math.min(W,Math.ceil(x+r));i++)if(Math.hypot(i-x,j-y)<=r&&fn(world[j][i],i,j))return{i,j,t:world[j][i]};return null}
function step(){tick++;if(tick%100===0){year++;annual()}for(let t of towns){t.age++;let pop=people.filter(p=>!p.dead&&p.home===t.id).length,c=civDefs[t.civ];if(pop===0)continue;let desired=Math.max(1,Math.ceil(pop/5));if(t.homes<desired&&c.wood>=8&&c.stone>=2){t.homes++;c.wood-=8;c.stone-=2;log(`${t.name} built a new homestead.`)}if(t.farms<Math.max(1,Math.floor(pop/4))&&c.wood>=4){t.farms++;c.wood-=4;log(`${t.name} planted a communal farm.`)}if(pop>=12&&!t.market&&c.wood>=10){t.market=1;c.wood-=10;log(`${t.name} opened a trading market.`)}if(t.level<5&&pop>=t.level*9&&c.stone>=6&&c.wood>=8){t.level++;c.stone-=6;c.wood-=8;log(`${t.name} grew into a level ${t.level} town.`)}if(pop>=19&&!t.ship&&c.wood>=15){t.ship=true;c.wood-=15;log(`${t.name} launched an exploration ship.`)}if(t.ship&&pop>=24&&rand()<.012){let p=nearbyTile(t.x,t.y,z=>z.b===0||z.b>0,30);let land=findLand(ir(W),ir(H),t.civ);if(land&&Math.hypot(land.x-t.x,land.y-t.y)>18&&towns.filter(a=>a.civ===t.civ).length<4){foundTown(t.civ,land.x,land.y);t.ship=false}}
}
for(let tileRow of world)for(let z of tileRow){if(z.b>0&&z.food<4&&rand()<.018)z.food++ ;if(z.wet>0)z.wet--}
for(let p of people){if(p.dead)continue;p.age+=.002;p.hunger+=.42;p.energy-=.18;if(p.health<100&&p.hunger<40)p.health+=.15;if(p.hunger>85){p.health-=.7;p.job='seek food'}if(p.energy<8)p.job='sleep';if(p.energy>92&&p.job==='sleep')p.job='gather';if(p.age>75)p.health-=.08;if(p.health<=0||p.age>105){p.dead=true;continue}
let home=towns[p.home];if(!home){p.dead=true;continue}let civ=civDefs[p.civ];
if(p.hunger>60){let foodSpot=nearbyTile(p.x,p.y,z=>z.food>0,10);if(foodSpot){moveTo(p,foodSpot.i,foodSpot.j,.07);if(Math.hypot(p.x-foodSpot.i,p.y-foodSpot.j)<.8){foodSpot.t.food--;p.hunger=Math.max(0,p.hunger-44);civ.food=Math.max(0,civ.food-1)}}else if(civ.food>0){civ.food--;p.hunger=Math.max(0,p.hunger-35)}}
if(p.energy<30){moveTo(p,home.x,home.y,.05);if(Math.hypot(p.x-home.x,p.y-home.y)<1.2)p.energy=Math.min(100,p.energy+1.4);continue}
if(p.job==='soldier'||(p.level>2&&rand()<.003)){}else p.job=rand()<.2?'farm':'gather';
let rad= p.job==='farm'?6:8,resource=p.job==='farm'?z=>z.b===1||z.b===2?z.food>0:false:z=>p.civ==='dwarf'?z.ore>0||z.stone>0:z.wood>0||z.food>0;
let spot=nearbyTile(p.x,p.y,resource,rad);if(!spot)spot=nearbyTile(home.x,home.y,resource,rad+4);if(spot){moveTo(p,spot.i,spot.j,.055);if(Math.hypot(p.x-spot.i,p.y-spot.j)<.8){p.work++;if(p.work>4){p.work=0;let z=spot.t;if(p.job==='farm'){if(z.food>0){z.food--;civ.food+=2+ (p.civ==='aurelin'?1:0)}}else if(p.civ==='dwarf'&&(z.ore>0||z.stone>0)){if(z.ore){z.ore--;civ.ore++;civ.coin++}else{z.stone--;civ.stone++}}else if(z.wood>0&&rand()<.58){z.wood--;civ.wood++;if(civ.wood%8===0&&civ.tools<30)civ.tools++}else if(z.food>0){z.food--;civ.food++}if(civ.food>14&&civ.wood>8&&rand()<.1){p.job='craft';civ.tools++;civ.wood-=2}}}}else moveTo(p,home.x,home.y,.035);
if(p.civ==='dwarf'&&p.level<2&&civ.tools>0){p.gear=1;p.level=2;civ.tools--}
}
// Births, civ growth and autonomous military / diplomacy.
for(let t of towns){let residents=people.filter(p=>!p.dead&&p.home===t.id);let adultF=residents.some(p=>p.gender==='♀'&&p.age>18&&p.age<43&&p.preg<=0),adultM=residents.some(p=>p.gender==='♂'&&p.age>18);if(residents.length<t.homes*5&&civDefs[t.civ].food>5&&adultF&&adultM&&rand()<.032){let mom=residents.find(p=>p.gender==='♀'&&p.age>18&&p.age<43&&p.preg<=0);if(mom){mom.preg=1;spawnPerson(t.civ,t.x,t.y,t.id,0);log(`A new child was born in ${t.name}.`)}}
if(residents.length>=8&&rand()<.003){let candidate=nearbyTile(t.x,t.y,z=>z.b>0,20);if(candidate&&towns.every(other=>Math.hypot(other.x-candidate.i,other.y-candidate.j)>10))foundTown(t.civ,candidate.i,candidate.j)}
if(residents.length>=6&&rand()<.025){let soldier=residents.find(p=>p.job!=='soldier');if(soldier&&civDefs[t.civ].tools>0){soldier.job='soldier';soldier.gear=1;civDefs[t.civ].tools--}}
}
for(let p of people)if(p.job==='soldier'&&!p.dead){let enemy=people.find(q=>!q.dead&&q.civ!==p.civ&&Math.hypot(q.x-p.x,q.y-p.y)<2.2);if(enemy){enemy.health-=p.gear?10:5;p.health-=enemy.gear?6:3;if(enemy.health<=0){enemy.dead=true;log(`${civDefs[p.civ].name} won a skirmish.`)}}else{let target=towns.find(t=>t.civ!==p.civ&&Math.hypot(t.x-p.x,t.y-p.y)<16);if(target)moveTo(p,target.x,target.y,.04)}}
for(let a of animals){a.age+=.003;if(a.energy<5){a.dead=true;continue}a.energy-=.05;if(rand()<.04){let dx=rand()*2-1,dy=rand()*2-1,tx=clamp(Math.round(a.x+dx),0,W-1),ty=clamp(Math.round(a.y+dy),0,H-1);if(world[ty][tx].b>0){a.x=tx;a.y=ty}}}
animals=animals.filter(a=>!a.dead);if(animals.length<90&&rand()<.08){let p=randomLand();if(p)animals.push({x:p.x,y:p.y,type:rand()<.6?'deer':'boar',age:0,energy:80,dir:0})}
if(rain>0)rain--;if(tick%8===0)refresh();}
function annual(){for(let c of Object.values(civDefs)){c.food=Math.max(0,c.food-2);c.coin+=c.food>15?1:0}for(let a of Object.keys(diplomacy)){if(diplomacy[a]>0&&rand()<.018){diplomacy[a]=0;log(`A border dispute strains relations.`)}else if(diplomacy[a]===0&&rand()<.01){diplomacy[a]=1;log(`A trade accord eases old tensions.`)}else if(diplomacy[a]===0&&rand()<.004){diplomacy[a]=-1;log(`War erupts between rival peoples!`);let k=a.split('');people.filter(p=>k.includes(p.civ)&&rand()<.4).forEach(p=>p.job='soldier')}}if(year%8===0)log(`Year ${year}: settlements prosper across the realm.`);document.getElementById('eraLabel').textContent=(year<15?'Dawn Age':year<35?'Age of Settlements':year<60?'Age of Crowns':'Age of Legends')+' · Year '+year}
function moveTo(p,x,y,v){let dx=x-p.x,dy=y-p.y,d=Math.hypot(dx,dy);if(d>.15){p.x+=dx/d*v;p.y+=dy/d*v}p.x=clamp(p.x,0,W-1);p.y=clamp(p.y,0,H-1)}

function fit(){let r=canvas.parentElement.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));ctx.imageSmoothingEnabled=false}window.addEventListener('resize',fit);
function render(){let w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);let base=Math.min(w/(W*T),h/(H*T)),s=base*cam.z;ctx.save();ctx.translate(w/2+cam.x,h/2+cam.y);ctx.scale(s,s);ctx.translate(-W*T/2,-H*T/2);
for(let y=0;y<H;y++)for(let x=0;x<W;x++){let z=world[y][x],px=x*T,py=y*T;ctx.fillStyle=colors[z.b];ctx.fillRect(px,py,T,T);let n=Math.abs(Math.sin((x*13.9+y*41.7+seed)*4.12));if(z.b===0){ctx.fillStyle=n>.65?'#32606a':n>.4?'#28545f':'#244d59';ctx.fillRect(px+2,py+3,4,1);if(n>.83){ctx.fillStyle='#47717a';ctx.fillRect(px+7,py+8,2,1)}}else{if(n>.72){ctx.fillStyle=z.b===4?'#92958b':z.b===5?'#eef0e8':z.b===3?'#d0ab69':z.b===2?'#638450':'#9cad64';ctx.fillRect(px+2+ir(4),py+2+ir(6),2,1)}if(z.b===2&&n>.32){ctx.fillStyle='#315d3b';ctx.fillRect(px+2,py+3,6,6);ctx.fillStyle='#71905a';ctx.fillRect(px+3,py+2,4,4);ctx.fillStyle='#533e2a';ctx.fillRect(px+5,py+8,2,3)}else if(z.b===4&&n>.25){ctx.fillStyle='#555e5b';ctx.fillRect(px+2,py+4,8,7);ctx.fillStyle='#a1a39a';ctx.fillRect(px+4,py+2,4,5)}else if(z.b===5&&n>.43){ctx.fillStyle='#eef1e8';ctx.fillRect(px+3,py+3,6,2)}else if(z.b===3&&n>.63){ctx.fillStyle='#ddbf81';ctx.fillRect(px+6,py+4,2,1)}}if(z.wet){ctx.fillStyle='#6b9b94';ctx.fillRect(px+3,py+4,6,3)}}
// trails and fields from villages
for(let t of towns){let c=civDefs[t.civ];ctx.fillStyle=c.color+'55';for(let i=-1;i<=1;i++)ctx.fillRect((t.x+i)*T+4,t.y*T+4,3,3);for(let n=0;n<t.farms;n++){let x=t.x+((n%3)-1)*2,y=t.y+Math.floor(n/3)*2+2;ctx.fillStyle='#b8ad63';ctx.fillRect(x*T,y*T,7,5);ctx.fillStyle='#6a7343';ctx.fillRect(x*T+1,y*T+1,1,3);ctx.fillRect(x*T+4,y*T+1,1,3)}}
for(let t of towns){let c=civDefs[t.civ];let s=1+Math.min(t.level,4)*.16;ctx.fillStyle='#15211e';ctx.fillRect(t.x*T+2,t.y*T+3,9*s,8*s);ctx.fillStyle='#a28761';ctx.fillRect(t.x*T+3,t.y*T+5,7*s,6*s);ctx.fillStyle=c.color;ctx.fillRect(t.x*T+2,t.y*T+3,9*s,3);ctx.fillStyle='#e7d5a5';ctx.fillRect(t.x*T+6,t.y*T+7,2,4);ctx.fillStyle='#d5c18d';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText(t.name,(t.x+.5)*T,(t.y-1)*T)}
for(let a of animals){let x=a.x*T,y=a.y*T;ctx.fillStyle=a.type==='deer'?'#d1b987':'#9d7160';ctx.fillRect(x+3,y+4,6,4);ctx.fillRect(x+7,y+2,3,3);ctx.fillStyle='#392d27';ctx.fillRect(x+4,y+8,1,2);ctx.fillRect(x+8,y+8,1,2);if(a.type==='deer'){ctx.fillStyle='#e5ddc1';ctx.fillRect(x+9,y+1,1,2)}}
for(let p of people){if(p.dead)continue;let x=Math.round(p.x*T),y=Math.round(p.y*T),c=civDefs[p.civ];ctx.fillStyle='#1a2020';ctx.fillRect(x+3,y+3,6,8);ctx.fillStyle=p.job==='soldier'?'#bd6559':c.color;ctx.fillRect(x+4,y+4,4,5);ctx.fillStyle=p.age<13?'#edcfaa':'#dfc99e';ctx.fillRect(x+4,y+1,4,4);ctx.fillStyle='#352920';ctx.fillRect(x+4,y+5,1,1);if(p.gear){ctx.fillStyle='#d3d5cb';ctx.fillRect(x+8,y+4,1,5)}}
for(let e of effects){ctx.globalAlpha=e.life/35;ctx.fillStyle=e.color;ctx.beginPath();ctx.arc(e.x*T,e.y*T,(35-e.life)*.6,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;e.life--}effects=effects.filter(e=>e.life>0);
if(tool!=='inspect'&&pointer.inside){ctx.strokeStyle='#fff0b0';ctx.lineWidth=1/s;ctx.strokeRect(pointer.x*T,pointer.y*T,T,T)}ctx.restore();requestAnimationFrame(render)}
let pointer={inside:false,x:0,y:0};function worldPos(e){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2),sx=(e.clientX-r.left)*d,sy=(e.clientY-r.top)*d,base=Math.min(canvas.width/(W*T),canvas.height/(H*T)),s=base*cam.z;return{x:Math.floor((sx-canvas.width/2-cam.x)/s/T+W/2),y:Math.floor((sy-canvas.height/2-cam.y)/s/T+H/2)}}
canvas.addEventListener('pointermove',e=>{let p=worldPos(e);pointer={...p,inside:true};if(drag){if(drag.mode==='pan'){cam.x+=e.clientX-drag.x;cam.y+=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY}else applyTool(p.x,p.y,true)}document.getElementById('coordLabel').textContent=`${p.x}, ${p.y} · ${tool.toUpperCase()}`});canvas.addEventListener('pointerleave',()=>pointer.inside=false);canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);let p=worldPos(e);if(tool==='inspect'&&e.button===0){drag={mode:'pan',x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};}else{drag={mode:'tool'};applyTool(p.x,p.y,false)}});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();cam.z=clamp(cam.z*(e.deltaY<0?1.12:.89),.65,4)},{passive:false});
function applyTool(x,y,stroke){if(x<0||y<0||x>=W||y>=H)return;let z=world[y][x],near=people.filter(p=>!p.dead&&Math.hypot(p.x-x,p.y-y)<3);if(tool==='inspect'){let t=towns.find(t=>Math.hypot(t.x-x,t.y-y)<2);let p=people.find(p=>!p.dead&&Math.hypot(p.x-x,p.y-y)<1);if(t){selected=t;toast(`${t.name} · ${civDefs[t.civ].race} · level ${t.level} · ${people.filter(p=>!p.dead&&p.home===t.id).length} residents`)}else if(p){selected=p;toast(`${civDefs[p.civ].race} · age ${Math.floor(p.age)} · ${p.job} · ${Math.round(p.health)} health · ${p.gender}`)}else toast(z.b===0?'Deep ocean':'Wild '+['','grassland','forest','desert','mountain','snowland'][z.b]+' · resources '+(z.food+z.wood+z.stone+z.ore));return}
if(tool==='human'||tool==='aurelin'||tool==='dwarf'){if(z.b===0){toast('Choose a shore or land tile.');return}let t=towns.find(t=>t.civ===tool&&Math.hypot(t.x-x,t.y-y)<8);if(!t)foundTown(tool,x,y);else spawnPerson(tool,x,y,t.id);log(`${civDefs[tool].race} answered your call.`);return}
if(tool==='forest'){if(z.b===0){toast('Forests need land.');return}z.b=2;z.wood=Math.min(5,z.wood+2);return}if(tool==='food'){z.food+=5;for(let p of near)if(p.hunger>25)p.hunger=Math.max(0,p.hunger-35);toast('A generous harvest!');return}if(tool==='rain'){rain=100;for(let yy=Math.max(0,y-3);yy<Math.min(H,y+4);yy++)for(let xx=Math.max(0,x-3);xx<Math.min(W,x+4);xx++){let q=world[yy][xx];q.wet=180;if(q.b===3&&rand()<.3)q.b=1;if(q.b===1||q.b===2)q.food=Math.min(5,q.food+2)}effects.push({x,y,life:35,color:'#85c9dc'});toast('Rain nourishes the land.');return}
if(tool==='lightning'||tool==='meteor'){let radius=tool==='meteor'?5:2;people.filter(p=>!p.dead&&Math.hypot(p.x-x,p.y-y)<radius).forEach(p=>{p.health-=tool==='meteor'?90:55;if(p.health<=0)p.dead=true});for(let yy=Math.max(0,y-radius);yy<Math.min(H,y+radius+1);yy++)for(let xx=Math.max(0,x-radius);xx<Math.min(W,x+radius+1);xx++)if(Math.hypot(xx-x,yy-y)<radius+1){let q=world[yy][xx];q.food=0;if(q.b===2){q.b=1;q.wood=Math.max(0,q.wood-2)}if(tool==='meteor'&&rand()<.55)q.b=0}effects.push({x,y,life:35,color:tool==='meteor'?'#ff8b57':'#eee7a5'});log(tool==='meteor'?'A meteor scarred the land!':'A bolt of divine lightning struck.');return}
