function refresh(){document.getElementById('popStat').textContent=people.filter(p=>!p.dead).length;document.getElementById('townStat').textContent=towns.length;document.getElementById('wildStat').textContent=animals.length;document.getElementById('yearStat').textContent=year;let all=['food','wood','stone','ore','tools','coin'];let ids=['foodStat','woodStat','stoneStat','oreStat','toolStat','coinStat'];all.forEach((k,i)=>document.getElementById(ids[i]).textContent=Object.values(civDefs).reduce((s,c)=>s+c[k],0));document.getElementById('civs').innerHTML=Object.entries(civDefs).map(([id,c])=>{let n=people.filter(p=>!p.dead&&p.civ===id).length,own=towns.filter(t=>t.civ===id).length;return `<div class="civ"><div class="sigil" style="background:${c.color}25;color:${c.color}">${c.icon}</div><div><div class="civname">${c.name}</div><div class="civdesc">${c.desc} · ${own} ${own===1?'settlement':'settlements'}</div></div><div class="civpop">${n}<small>people</small></div></div>`}).join('')}
function toast(text){let el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
document.querySelectorAll('.tool').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('.tool').forEach(x=>x.classList.toggle('active',x===b));toast(`${b.textContent.trim().replace(/\s+/g,' ')} selected · tap the world`)});
document.querySelectorAll('.speedbtn').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;document.querySelectorAll('.speedbtn').forEach(x=>x.classList.toggle('primary',x===b));toast(`Simulation speed ${speed}×`)});
function togglePause(){paused=!paused;document.getElementById('pauseBtn').textContent=paused?'▶ Resume':'Ⅱ Pause';document.getElementById('pauseBtn').classList.toggle('primary',!paused)}document.getElementById('pauseBtn').onclick=togglePause;document.getElementById('stepBtn').onclick=()=>{if(paused){step();toast('One simulation step.')}else toast('Pause first to advance one step.')};
document.getElementById('saveBtn').onclick=()=>{try{localStorage.setItem('mytherio-save',JSON.stringify({world,people,animals,towns,civDefs,diplomacy,seed,year,tick,worldName:document.getElementById('worldName').textContent}));toast('Realm saved on this device.')}catch(e){toast('Save failed: storage is full.')}};document.getElementById('loadBtn').onclick=()=>{try{let s=JSON.parse(localStorage.getItem('mytherio-save'));if(!s){toast('No saved realm found.');return}world=s.world;people=s.people;animals=s.animals;towns=s.towns;Object.assign(civDefs,s.civDefs);diplomacy=s.diplomacy;seed=s.seed;year=s.year;tick=s.tick;document.getElementById('worldName').textContent=s.worldName;document.getElementById('seedLabel').textContent='WORLD '+String(seed).padStart(5,'0');document.getElementById('eraLabel').textContent='Year '+year;refresh();toast('Realm restored.')}catch(e){toast('Could not load saved realm.')}};
window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();togglePause()}if(e.key==='1'||e.key==='2'||e.key==='3')speed=[1,3,8][+e.key-1]});
function frame(now){let dt=Math.min(.1,(now-last)/1000);last=now;if(!paused){acc+=dt*speed;while(acc>=.14){step();acc-=.14}}requestAnimationFrame(frame)}
generate();render();requestAnimationFrame(frame);
</script></body></html>

