for(let row of world)for(let z of row)if(z.b>0&&z.food<4&&rand()<.018)z.food++;
for(let p of people){if(p.dead)continue;p.age+=.002;p.hunger+=.42;p.energy-=.18;if(p.health<100&&p.hunger<40)p.health+=.15;if(p.hunger>85)p.health-=.7;if(p.energy<8)p.job='sleep';if(p.energy>92&&p.job==='sleep')p.job='gather';if(p.age>75)p.health-=.08;if(p.health<=0||p.age>105){p.dead=true;continue}let home=towns[p.home],c=stores[p.civ];if(!home){p.dead=true;continue}if(p.hunger>60){let f=near(p.x,p.y,z=>z.food>0,10);if(f){move(p,f.i,f.j,.07);if(Math.hypot(p.x-f.i,p.y-f.j)<.8){f.t.food--;p.hunger=Math.max(0,p.hunger-44);c.food=Math.max(0,c.food-1)}}else if(c.food){c.food--;p.hunger=Math.max(0,p.hunger-35)}}if(p.energy<30){move(p,home.x,home.y,.05);if(Math.hypot(p.x-home.x,p.y-home.y)<1.2)p.energy=Math.min(100,p.energy+1.4);continue}if(p.job!=='soldier')p.job=rand()<.2?'farm':'gather';let pred=p.job==='farm'?z=>z.food>0&&(z.b===1||z.b===2):p.civ==='dwarf'?z=>z.ore>0||z.stone>0:z=>z.wood>0||z.food>0;let spot=near(p.x,p.y,pred,p.job==='farm'?6:8)||near(home.x,home.y,pred,12);if(spot){move(p,spot.i,spot.j,.055);if(Math.hypot(p.x-spot.i,p.y-spot.j)<.8&&++p.work>4){p.work=0;let z=spot.t;if(p.job==='farm'&&z.food){z.food--;c.food+=2+(p.civ==='aurelin'?1:0)}else if(p.civ==='dwarf'&&(z.ore||z.stone)){if(z.ore){z.ore--;c.ore++;c.coin++}else{z.stone--;c.stone++}}else if(z.wood&&rand()<.58){z.wood--;c.wood++;if(c.wood%8===0&&c.tools<30)c.tools++}else if(z.food){z.food--;c.food++}if(c.food>14&&c.wood>8&&rand()<.1){c.tools++;c.wood-=2}}}else move(p,home.x,home.y,.035);if(p.civ==='dwarf'&&p.level<2&&c.tools){p.gear=1;p.level=2;c.tools--}}
