function fit(){let r=canvas.parentElement.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,r.width*d);canvas.height=Math.max(1,r.height*d);ctx.imageSmoothingEnabled=false}window.addEventListener('resize',fit);
