':defs[p.civ].color;ctx.fillRect(x+4,y+4,4,5);ctx.fillStyle='#dfc99e';ctx.fillRect(x+4,y+1,4,4);if(p.gear){ctx.fillStyle='#d3d5cb';ctx.fillRect(x+8,y+4,1,5)}}effects.forEach(e=>{ctx.globalAlpha=e.life/35;ctx.fillStyle=e.color;ctx.beginPath();ctx.arc(e.x*T,e.y*T,(35-e.life)*.6,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;e.life--});effects=effects.filter(e=>e.life>0);if(tool!=='inspect'&&pointer.inside){ctx.strokeStyle='#fff0b0';ctx.lineWidth=1/s;ctx.strokeRect(pointer.x*T,pointer.y*T,T,T)}ctx.restore();requestAnimationFrame(render)}

