 </style></head><body><div class="app"><header><div class="brand">MYTHERIO <span>✦</span></div><div class="subtitle">LIVING REALMS · WORLD SIMULATOR</div><div class="headright"><span class="seed" id="seed">WORLD 00000</span><button class="pill" id="save">◈ Save world</button><button class="pill" id="load">↻ Load</button></div></header><main class="main"><section class="world-wrap"><div class="world-top"><strong id="worldname">The Verdant Reach</strong><span style="margin-left:8px">·</span><span id="era" style="margin-left:8px">Dawn Age · Year 1</span><span class="coords" id="coords">DRAG TO PAN · SCROLL TO ZOOM</span></div><div class="canvasbox"><canvas id="map"></canvas><div class="maplabel">✦ &nbsp;MYTHERIO ARCHIPELAGO</div><div class="maplegend"><div class="legenditem"><i class="dot" style="background:#527746"></i>Forest</div><div class="legenditem"><i class="dot" style="background:#879c57"></i>Grassland</div><div class="legenditem"><i class="dot" style="background:#b99156"></i>Desert</div><div class="legenditem"><i class="dot" style="background:#747b73"></i>Mountain</div><div class="legenditem"><i class="dot" style="background:#d5d9d0"></i>Snowland</div></div><div class="toast" id="toast"></div></div></section><aside class="side"><div class="controls"><div class="section-title">SIMULATION CONTROL</div><div class="simrow"><button id="pause" class="controlbtn primary">Ⅱ Pause</button><button id="stepbtn" class="controlbtn">▶ Step</button><div class="speed"><button class="controlbtn speedbtn" data-speed="1">1×</button><button class="controlbtn speedbtn" data-speed="3">3×</button><button class="controlbtn speedbtn" data-speed="8">8×</button></div></div></div><div class="panel"><div class="section-title">WORLD STATUS</div><div class="stats"><div class="stat"><label>POPULATION</label><strong id="pop">0</strong><small>living</small></div><div class="stat"><label>SETTLEMENTS</label><strong id="towncount">0</strong><small>villages</small></div><div class="stat"><label>WI