an>MYTHERIO SIM ENGINE v1.0</span><span>✦ All lives matter</span></div></aside></main></div><script>
 const canvas=document.querySelector('#map'),ctx=canvas.getContext('2d'),W=104,H=72,T=12,colors=['#234a55','#879c57','#527746','#b99156','#747b73','#d5d9d0'];let world=[],people=[],animals=[],towns=[],effects=[],seed=0,year=1,tick=0,paused=false,speed=1,tool='inspect',cam={x:0,y:0,z:1},acc=0,last=performance.now(),drag=null,pointer={x:0,y:0,inside:false},rain=0;const defs={human:{name:'The Hearthwardens',race:'Humans',icon:'♟',color:'#d7a85d',desc:'Adaptable · balanced growth'},aurelin:{name:'Elderbloom Court',race:'Aurelin',icon:'❋',color:'#86c77f',desc:'Nature specialists · forest-born'},dwarf:{name:'Ironvein Holds',race:'Dwarves',icon:'⚒',color:'#b887b9',desc:'Mining & craft · stone-born'}};let stores={},diplomacy={};const rand=Math.random,ir=n=>Math.floor(rand()*n),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
