 function step(){tick++;if(tick%100===0){year++;annual()}for(let t of towns){let c=stores[t.civ],pop=people.filter(p=>!p.dead&&p.home===t.id).length;if(!pop)continue;if(t.homes<Math.ceil(pop/5)&&c.wood>=8&&c.stone>=2){t.homes++;c.wood-=8;c.stone-=2;log(`${t.name} built a homestead.`)}if(t.farms<Math.max(1,Math.floor(pop/4))&&c.wood>=4){t.farms++;c.wood-=4}if(pop>=12&&!t.market&&c.wood>=10){t.market=1;c.wood-=10;log(`${t.name} opened a trading market.`)}if(t.level<5&&pop>=t.level*9&&c.stone>=6&&c.wood>=8){t.level++;c.stone-=6;c.wood-=8}if(pop>=19&&!t.ship&&c.wood>=15){t.ship=true;c.wood-=15}if(t.ship&&pop>=24&&rand()<.012){let p=findLand(ir(W),ir(H),t.civ);if(p&&Math.hypot(p.x-t.x,p.y-t.y)>18&&towns.filter(a=>a.civ===t.civ).length<4){foundTown(t.civ,p.x,p.y);t.ship=false}}}
